import{_ as a,o as r,c as s,a2 as i}from"./chunks/framework.CqGPl1zp.js";const o="/newx-doc/assets/%E8%AE%A2%E9%98%85%E6%B6%88%E6%81%AF%E6%A8%A1%E7%89%88.CnklX--3.png",t="/newx-doc/assets/%E8%AE%A2%E5%8D%95%E5%8F%91%E8%B4%A7%E9%80%9A%E7%9F%A5.Dki6YYPF.png",p="/newx-doc/assets/%E6%8B%BC%E5%9B%A2%E7%BB%93%E6%9E%9C%E9%80%9A%E7%9F%A5.BPSl45v2.png",l="/newx-doc/assets/%E5%85%85%E5%80%BC%E6%88%90%E5%8A%9F%E9%80%9A%E7%9F%A5.UwiX2wqG.png",n="/newx-doc/assets/%E5%90%8E%E7%AB%AF%E9%85%8D%E7%BD%AE-boot.BUIuwJBC.png",c="/newx-doc/assets/%E6%94%AF%E4%BB%98%E6%88%90%E5%8A%9F%E9%A1%B5.DsKYNr16.png",d="/newx-doc/assets/%E5%8F%91%E8%B5%B7%E8%AE%A2%E9%98%85%E6%B6%88%E6%81%AF.BBaKXGBL.png",m="/newx-doc/assets/%E8%AE%A2%E5%8D%95%E5%8F%91%E8%B4%A7.DzqQ59gC.png",u="/newx-doc/assets/%E6%9C%8D%E5%8A%A1%E9%80%9A%E7%9F%A5.BxNg0MOn.png",q=JSON.parse('{"title":"微信小程序订阅消息","description":"","frontmatter":{},"headers":[],"relativePath":"member/weixin-lite-subscribe-message.md","filePath":"member/weixin-lite-subscribe-message.md","lastUpdated":null}'),g={name:"member/weixin-lite-subscribe-message.md"};function b(h,e,_,E,f,A){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="微信小程序订阅消息" tabindex="-1">微信小程序订阅消息 <a class="header-anchor" href="#微信小程序订阅消息" aria-label="Permalink to &quot;微信小程序订阅消息&quot;">​</a></h1><p>前置阅读文章：</p><ul><li><a href="./../user-center">《用户体系》</a></li><li><a href="./../social-user">《三方登录》</a></li></ul><p>本文是 <a href="./../social-user">《三方登录》</a> 的延伸，讲解 <a href="https://github.com/yudaocode/yudao-mall-uniapp" target="_blank" rel="noreferrer"><code>yudao-mall-uniapp</code></a> 商城小程序如何实现微信 <strong>小程序</strong> 订阅消息的功能。对应的官方文档如下：</p><ul><li><a href="https://developers.weixin.qq.com/miniprogram/dev/framework/open-ability/subscribe-message-overview.html" target="_blank" rel="noreferrer">《【开发指南】订阅消息》</a></li><li><a href="https://developers.weixin.qq.com/miniprogram/dev/api/open-api/subscribe-message/wx.requestSubscribeMessage.html" target="_blank" rel="noreferrer">《【前端】订阅消息》</a></li><li><a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/mp-message-management/subscribe-message/deleteMessageTemplate.html" target="_blank" rel="noreferrer">《【服务端】订阅消息》</a></li></ul><h2 id="_1-小程序准备" tabindex="-1">1. 小程序准备 <a class="header-anchor" href="#_1-小程序准备" aria-label="Permalink to &quot;1. 小程序准备&quot;">​</a></h2><h3 id="_1-1-模版申请" tabindex="-1">1.1 模版申请 <a class="header-anchor" href="#_1-1-模版申请" aria-label="Permalink to &quot;1.1 模版申请&quot;">​</a></h3><p>目前订阅消息，无法使用之前的“测试小程序”，必须进行正式小程序的申请！</p><p>申请后，可以在 [微信小程序 -&gt; 功能 -&gt; 订阅消息] 菜单，申请对应的订阅消息模版。如下图所示：</p><p><img src="'+o+'" alt="订阅消息"></p><p>上图可以看到三个模版，是目前项目已经接入的订阅消息：</p><ul><li>【商城】订单发货通知：管理员在后台发货后，通知用户 <img src="'+t+'" alt="订单发货通知"></li><li>【商城】拼团结果通知：用户拼团成功后，通知用户 <img src="'+p+'" alt="拼团结果通知"></li><li>【支付】充值成功通知：用户充值成功后，通知用户 <img src="'+l+'" alt="充值成功通知"></li></ul><p>而这些模版，我们是无法编辑，而是在【公共模板库】选用后，进入【我的模版】。</p><h3 id="_1-2-后端配置" tabindex="-1">1.2 后端配置 <a class="header-anchor" href="#_1-2-后端配置" aria-label="Permalink to &quot;1.2 后端配置&quot;">​</a></h3><p>在后端 <a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/mp-message-management/subscribe-message/sendMessage.html" target="_blank" rel="noreferrer">发送订阅消息</a> 时，需要传递 <code>miniprogram_state</code> 参数，用于区分跳转小程序类型：</p><ul><li><code>developer</code> 为开发版</li><li><code>trial</code> 为体验版</li><li><code>formal</code> 为正式版</li></ul><p>因此，在 <code>application-${profile}.yaml</code> 配置文件中，有对应的 <code>yudao.wxa-subscribe-message.miniprogram-state</code> 配置项，如下图所示：</p><p><img src="'+n+'" alt="后端配置"></p><p>一般情况下，如果是开发测试，不用修改，直接使用默认的 <code>developer</code> 即可。</p><h2 id="_2-功能演示-代码实现" tabindex="-1">2. 功能演示 &amp; 代码实现 <a class="header-anchor" href="#_2-功能演示-代码实现" aria-label="Permalink to &quot;2. 功能演示 &amp; 代码实现&quot;">​</a></h2><p>本小节，我们以【商城】订单发货通知为例，演示如何实现订阅消息的功能。在开始之前，你需要做如下事情：</p><ul><li>参考 <a href="./../quick-start-front">《快速启动【前端】》</a> 文档，把 <code>yudao-uniapp-mall</code> 商城项目跑起来，并使用 HBuilderX + 微信开发者工具进行调试</li><li>参考 <a href="./../mall/build">《商城功能开启》</a> 文档，开启商城功能</li><li>在 [微信小程序 -&gt; 功能 -&gt; 订阅消息] 菜单，配置好“订单发货通知”模版</li></ul><h3 id="_2-1-uni-app-获取订阅模版列表" tabindex="-1">2.1 uni-app 获取订阅模版列表 <a class="header-anchor" href="#_2-1-uni-app-获取订阅模版列表" aria-label="Permalink to &quot;2.1 uni-app 获取订阅模版列表&quot;">​</a></h3><p>在 uni-app 打开时，会调用后端的 AppSocialUserController 的 <code>#getSubscribeTemplateList()</code> 方法，获取订阅消息模版列表。</p><p>目的是，uni-app 在调用 <a href="https://developers.weixin.qq.com/miniprogram/dev/api/open-api/subscribe-message/wx.requestSubscribeMessage.html" target="_blank" rel="noreferrer"><code>wx.requestSubscribeMessage(Object object)</code></a> 发起订阅消息时，需要传递 <code>tmplIds</code> 消息模版的编号。</p><p>友情提示：</p><p>由于暂时没做微信小程序的订阅消息的模版管理，所以暂时通过它的模版名称来匹配的。算是约定大于配置吧~</p><p>不过因为小程序的订阅消息模版是只能 <strong>选用</strong>，标题是固定的，所以这个约定是可行的。</p><h3 id="_2-2-uni-app-发起订阅消息" tabindex="-1">2.2 uni-app 发起订阅消息 <a class="header-anchor" href="#_2-2-uni-app-发起订阅消息" aria-label="Permalink to &quot;2.2 uni-app 发起订阅消息&quot;">​</a></h3><p>第一步，在 uni-app 中，下单并完成支付，然后会进入支付成功页。如下图所示：</p><p><img src="'+c+'" alt="支付成功页"></p><p>第二步，点击【立即订阅】按钮，发起对“订单发货通知”的订阅消息。如下图所示：</p><p><img src="'+d+'" alt="发起订阅消息"></p><p>它的实现，通过调用项目的 <code>sheep/platform/provider/wechat/miniProgram.js</code> 的 <code>#subscribeMessage(...)</code> 方法，从而调用微信的 <code>wx.requestSubscribeMessage(Object object)</code> 方法，发起订阅消息的请求。</p><h3 id="_2-3-后端发送订阅消息" tabindex="-1">2.3 后端发送订阅消息 <a class="header-anchor" href="#_2-3-后端发送订阅消息" aria-label="Permalink to &quot;2.3 后端发送订阅消息&quot;">​</a></h3><p>第一步，在管理后台，点击 [商城系统 -&gt; 订单中心 -&gt; 订单列表] 菜单，找到对应的订单，点击【发货】按钮，发起对订单的发货操作。如下图所示：</p><p><img src="'+m+'" alt="订单发货"></p><p>它的内部，通过调用项目的 SocialClientApi 的 <code>#sendWxaSubscribeMessage(...)</code> 方法，从而调用微信的 <a href="https://developers.weixin.qq.com/miniprogram/dev/OpenApiDoc/mp-message-management/subscribe-message/sendMessage.html" target="_blank" rel="noreferrer">发送订阅消息</a> 接口，发送订阅消息的请求。</p><p>第二步，拿出手机微信（PC 电脑上看不到），在【服务通知】中，可以看到对应的订阅消息。如下图所示：</p><p><img src="'+u+'" alt="服务通知"></p><p>如果没有收到订阅消息，可以在 IDEA 控制台，搜 <code>[sendSubscribeMessage]</code> 关键字，查看是否有异常日志输出。</p><h2 id="_3-其它业务如何接入" tabindex="-1">3. 其它业务如何接入？ <a class="header-anchor" href="#_3-其它业务如何接入" aria-label="Permalink to &quot;3. 其它业务如何接入？&quot;">​</a></h2><p>参考上述小节的内容：</p><ul><li>第一步，在 uni-app 项目中，需要调用项目的 <code>sheep/platform/provider/wechat/miniProgram.js</code> 的 <code>#subscribeMessage(...)</code> 方法，发起订阅</li><li>第二步，在后端项目中，需要调用 SocialClientApi 的 <code>#sendWxaSubscribeMessage(...)</code> 方法，发送订阅消息</li></ul><p>当然，肯定需要在微信小程序那，配置对应的订阅消息模版。</p>',45)])])}const w=a(g,[["render",b]]);export{q as __pageData,w as default};
